/**
 * {@link FixtureDataSource}: a {@link WebDataSource} that reads a
 * `.slop`-shaped directory straight off disk (design.md §3's layout —
 * `config.yaml`, `db/tickets/*.jsonc`, `db/sessions/*.jsonc`,
 * `db/events/*.jsonc`) with plain filesystem calls,
 * validating every file against the A2 zod schemas so a malformed fixture
 * fails loudly instead of silently drifting from the real shapes.
 *
 * This work item points it at the committed fixture db
 * (tests/fixtures/web-db/.slop/, generated by
 * tests/fixtures/generate-web-db.ts) — hence the name — but nothing about
 * the implementation is fixture-specific: it works against *any* directory
 * in this shape, including a real project's `.slop/`.
 *
 * G2 (pluggable storage backend): `src/cli/commands/web.ts` no longer uses
 * this class for the real repo case — that's
 * {@link ../storage-data-source.js!StorageDataSource}'s job now, backed by
 * `StorageBackend` (config-selected flatfile/remote driver, the flatfile
 * one's in-process read cache, shard-aware event reads). This class
 * remains exactly what its name says: the fixture-backed `WebDataSource`
 * used by tests exercising the interface's contract against a committed,
 * self-contained fixture db, independent of the storage layer — its own
 * "deliberately NOT reused from src/repo/" design below is still exactly
 * right for that job, and there is no reason to change it now that a real
 * adapter exists elsewhere.
 *
 * Deliberately NOT reused from src/repo/ (originally so this lane could be
 * built concurrently with, and without depending on, the repo layer):
 * there is no locking, no atomic writes (this class never writes), no
 * persisted `index.jsonc` — `blocked`/`stale` and the reverse blocks-edge
 * index are recomputed in memory on every call (src/web/overlays.ts).
 */
import { readdir } from "node:fs/promises";
import { join } from "node:path";
import {
  type Event,
  eventSchema,
  parseJsonc,
  type Session,
  sessionSchema,
  type Ticket,
  type TicketId,
  ticketSchema,
} from "../core/index.js";
import type { ConfigResult, WebDataSource } from "./data-source.js";
import { readSlopConfigTolerant } from "./data-source.js";
import { matchTicketByRef } from "./overlays.js";

/**
 * web-one-malformed-db-file-500s-every-page-and-leaks-filesyst: this used
 * to read+parse every file in `dir` strictly (`for` loop, first throw wins)
 * — which meant one corrupt/schema-drifted `.jsonc` file took the ENTIRE
 * listing down with it, and every view built on that listing along with it
 * (`/tickets`, `/tree`, `/review`, `/stale`, and — via `findTicketByRef`
 * re-`listTickets()`-ing — even an unrelated ticket's own detail page).
 *
 * Mirrors the fault-tolerant `Promise.allSettled` pattern
 * `repo/tickets.ts`'s `listTicketsTolerant` (reused by `repo/db-index.ts`'s
 * `buildIndex`, see that module's "Fault tolerance" doc section) already
 * established for exactly this class of problem: a file that fails to
 * read, parse as JSONC, or validate against its schema is skipped and
 * logged (stderr, via {@link warnSkippedFiles}) rather than aborting the
 * whole directory read. Every other file in `dir` is still returned,
 * unaffected — so one bad ticket/session/event file degrades to "N fewer
 * rows in the listing", never a 500 on every page that listing feeds.
 *
 * Direct single-entity reads (`getSessionById`, `getConfig`) are
 * deliberately UNCHANGED and still throw on a corrupt file — same
 * reasoning `repo/tickets.ts`'s `readTicket`/`listTickets` doc gives: a
 * direct-by-id read is the caller asking for that exact entity and has no
 * sensible "skip it" option. This function is only ever used for
 * *listings* (`listTickets`, the sessions/events dirs) — see this module's
 * callers.
 */
async function readJsoncDir<T>(
  dir: string,
  parseOne: (text: string, file: string) => T,
): Promise<T[]> {
  let entries: string[];
  try {
    entries = await readdir(dir);
  } catch (err) {
    if (err instanceof Error && "code" in err && err.code === "ENOENT") return [];
    throw err;
  }
  const files = entries.filter((name) => name.endsWith(".jsonc")).sort();
  const settled = await Promise.allSettled(
    files.map(async (file) => {
      const path = join(dir, file);
      const text = await Bun.file(path).text();
      return parseOne(text, path);
    }),
  );

  const out: T[] = [];
  const skipped: string[] = [];
  for (const result of settled) {
    if (result.status === "fulfilled") {
      out.push(result.value);
    } else {
      const message =
        result.reason instanceof Error ? result.reason.message : String(result.reason);
      skipped.push(message);
    }
  }
  if (skipped.length > 0) warnSkippedFiles(dir, skipped);
  return out;
}

/**
 * Never-silent counterpart to the skip-and-continue behaviour above —
 * matches `repo/db-index.ts`'s `warnAboutIndexProblems`: a skipped file is
 * degraded service, not something that should vanish without a trace.
 * stderr only (this is a read-only local dev server; there is no request
 * -scoped logger to route through), one line per directory read that hit
 * at least one bad file, each skipped file's own high-quality parse/schema
 * error indented beneath it.
 */
function warnSkippedFiles(dir: string, messages: string[]): void {
  const header = `slop web: ${messages.length} file(s) in ${dir} failed to load and were skipped:`;
  const body = messages.map((message) => `  - ${message}`).join("\n");
  process.stderr.write(`${header}\n${body}\n`);
}

function parseEntity<T>(schema: { parse: (input: unknown) => T }, text: string, path: string): T {
  const { value, errors } = parseJsonc<unknown>(text);
  if (errors.length > 0) {
    throw new Error(`${path}: invalid JSONC (${errors.length} parse error(s))`);
  }
  try {
    return schema.parse(value);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    throw new Error(`${path}: failed schema validation — ${message}`);
  }
}

export class FixtureDataSource implements WebDataSource {
  /** Root of a `.slop` directory (design.md §3) — the directory that directly contains `config.yaml` and `db/`. */
  constructor(private readonly slopRoot: string) {}

  /** See {@link readSlopConfigTolerant} — the shared tolerant reader every `WebDataSource`'s `getConfig()` uses. */
  async getConfig(): Promise<ConfigResult> {
    return readSlopConfigTolerant(this.slopRoot);
  }

  async listTickets(): Promise<Ticket[]> {
    return readJsoncDir(join(this.slopRoot, "db", "tickets"), (text, path) =>
      parseEntity(ticketSchema, text, path),
    );
  }

  async findTicketByRef(ref: string): Promise<Ticket | null> {
    // web-every-request-full-rescans: the matching rule itself lives in
    // overlays.ts's matchTicketByRef (also used directly by
    // handleTicketDetail, which already has to fetch the full ticket list
    // anyway) so there's exactly one implementation of "which id does this
    // ref mean", not two independently-drifting ones.
    return matchTicketByRef(await this.listTickets(), ref);
  }

  async listSessionsForTicket(ticketId: TicketId): Promise<Session[]> {
    const all = await readJsoncDir(join(this.slopRoot, "db", "sessions"), (text, path) =>
      parseEntity(sessionSchema, text, path),
    );
    return all
      .filter((s) => s.ticket === ticketId)
      .sort((a, b) => a.started_at.localeCompare(b.started_at));
  }

  /** The full `db/events/` directory, fault-tolerantly read — shared by
   * {@link listEventsForTicket} and {@link listEvents} so the two never
   * drift on what counts as a readable event file. */
  private readAllEvents(): Promise<Event[]> {
    return readJsoncDir(join(this.slopRoot, "db", "events"), (text, path) =>
      parseEntity(eventSchema, text, path),
    );
  }

  async listEventsForTicket(
    ticketId: TicketId,
    knownSessions?: readonly Session[],
  ): Promise<Event[]> {
    // web-every-request-full-rescans: a caller that already fetched this
    // ticket's sessions (handleTicketDetail does, for its own "Sessions"
    // section) can pass them in via `knownSessions` to skip re-scanning the
    // sessions directory a second time in the same request.
    const [events, sessions] = await Promise.all([
      this.readAllEvents(),
      knownSessions ? Promise.resolve(knownSessions) : this.listSessionsForTicket(ticketId),
    ]);
    const sessionIds = new Set<string>(sessions.map((s) => s.id));
    const relevant = events.filter(
      (e) =>
        (e.entity.kind === "ticket" && e.entity.id === ticketId) ||
        (e.entity.kind === "session" && sessionIds.has(e.entity.id)),
    );
    // Event ids are ULIDs (D6): lexicographic order is chronological order.
    return relevant.sort((a, b) => a.id.localeCompare(b.id));
  }

  async listEvents(): Promise<Event[]> {
    return this.readAllEvents();
  }
}
